# Linguística — lote L16 (ponto L13: LC 95/1998 e técnica legislativa; texto compilado do Planalto e Manual de Redação, 3ª ed., lidos nos PDFs do usuário)
Q = []
TAILS=[" Essa seria a leitura predominante em técnica legislativa.",
 " Trata-se de orientação corrente na elaboração das leis.",
 " Tal solução decorreria, segundo esse entendimento, da natureza do ato normativo.",
 " Essa seria a recomendação mais aceita pela doutrina de técnica legislativa."]
SHORT=[" Isso é consenso na área."," Essa é a regra geral."," Trata-se de prática corrente."," Esse é o entendimento usual."]
def tail(E,C,i):
    gap=len(C)-len(E)
    if len(E) < 0.97*len(C) and gap > 60: return E+TAILS[i%len(TAILS)]
    if len(E) < 0.95*len(C) and gap > 8: return E+SHORT[i%len(SHORT)]
    return E
def P(ponto, arts, padC, padE, dif, C, E, com, terro, tag, ref, tipo, conh):
    if conh:
        ex={"fonte":{"tipo":"doutrina","ref":ref,"versao":"conhecimento do autor","conferida":"conhecimento"},"risco":["doutrina_conhecimento"]}
    elif tipo=="lei":
        ex={"fonte":{"tipo":"lei","ref":ref,"versao":"texto compilado (LC 107/2001)","conferida":"pdf_usuario"}}
    else:
        ex={"fonte":{"tipo":"doutrina","ref":ref,"versao":"3ª ed., 2018","conferida":"pdf_usuario"}}
    E = tail(E, C, len(Q))
    padC = padE if padC == 'conceito_correto' else padC
    Q.append((ponto, arts, "C", padC, dif, C, com, "", tag, ex))
    Q.append((ponto, arts, "E", padE, dif, E, com, terro, tag, ex))
_n=[0]
def L(atom, padE, dif, C, E, com, terro, ref, conh=False):
    """Item da LC 95/1998 (ref = 'art. X')."""
    _n[0]+=1
    P("L13",[str(atom)],"conceito_correto",padE,dif,C,E,com,terro,f"z{_n[0]:02d}","LC 95/1998, "+ref,"lei",conh)
def T(atom, padE, dif, C, E, com, terro, ref, conh=False):
    """Item de técnica legislativa do Manual de Redação (ref = 'item X')."""
    _n[0]+=1
    P("L13",[str(atom)],"conceito_correto",padE,dif,C,E,com,terro,f"z{_n[0]:02d}","Manual de Redação da Presidência da República, 3ª ed. (2018), "+ref,"manual",conh)
# ---- atom 13: arts. 1º a 9º e 19
L(13,"confusao_instituto",2,"A LC 95/1998 dispõe sobre a elaboração, a redação, a alteração e a consolidação das leis, conforme determina o parágrafo único do art. 59 da Constituição Federal, e estabelece normas para a consolidação dos atos normativos que menciona.","A LC 95/1998 dispõe sobre o processo legislativo, regulando a iniciativa, a sanção, o veto e os quóruns de votação das leis, conforme determina o art. 61 da Constituição Federal.","LC 95/1998, ementa.","atribui conteúdo de processo legislativo","ementa")
L(13,"restricao_indevida",3,"As disposições da LC 95/1998 aplicam-se também às medidas provisórias e aos demais atos normativos referidos no art. 59 da Constituição e, no que couber, aos decretos e aos demais atos de regulamentação expedidos por órgãos do Poder Executivo.","As disposições da LC 95/1998 aplicam-se às leis ordinárias e complementares, não alcançando as medidas provisórias nem os decretos e demais atos de regulamentação expedidos por órgãos do Poder Executivo.","LC 95/1998, art. 1º, parágrafo único.","restringe campo de aplicação","art. 1º, parágrafo único")
L(13,"troca_numero",4,"Na numeração das leis, as emendas à Constituição têm numeração iniciada a partir da promulgação da Constituição de 1988, e as leis complementares, ordinárias e delegadas têm numeração sequencial em continuidade às séries iniciadas em 1946.","Na numeração das leis, as emendas à Constituição têm numeração sequencial em continuidade à série iniciada em 1946, e as leis complementares, ordinárias e delegadas têm numeração iniciada a partir da promulgação da Constituição de 1988.","LC 95/1998, art. 2º, § 2º.","troca marcos da numeração","art. 2º, § 2º")
L(13,"confusao_instituto",3,"A lei é estruturada em três partes básicas: a parte preliminar, a parte normativa e a parte final.","A lei é estruturada em quatro partes básicas: a parte preliminar, a parte normativa, a parte final e a parte de motivação.","LC 95/1998, art. 3º.","acrescenta parte inexistente","art. 3º")
L(13,"confusao_instituto",3,"Integram a parte preliminar da lei a epígrafe, a ementa, o preâmbulo, o enunciado do objeto e a indicação do âmbito de aplicação das disposições normativas.","Integram a parte preliminar da lei a epígrafe, a ementa, o preâmbulo, as disposições transitórias e a cláusula de vigência.","LC 95/1998, art. 3º, I.","move elementos da parte final","art. 3º, I")
L(13,"confusao_instituto",3,"Integram a parte final da lei as disposições pertinentes às medidas necessárias à implementação das normas de conteúdo substantivo, as disposições transitórias, se for o caso, a cláusula de vigência e a cláusula de revogação, quando couber.","Integram a parte final da lei as disposições pertinentes às medidas necessárias à implementação das normas de conteúdo substantivo, o enunciado do objeto, a indicação do âmbito de aplicação e a cláusula de vigência.","LC 95/1998, art. 3º, III.","move elementos da parte preliminar","art. 3º, III")
L(13,"troca_efeito",3,"A epígrafe da lei, grafada em caracteres maiúsculos, propicia identificação numérica singular à lei e é formada pelo título designativo da espécie normativa, pelo número respectivo e pelo ano de promulgação.","A epígrafe da lei, grafada em caracteres minúsculos, explicita o objeto da lei e é formada pelo título designativo da espécie normativa e pela ementa, sem número nem ano.","LC 95/1998, art. 4º.","mistura epígrafe e ementa","art. 4º")
L(13,"confusao_instituto",3,"A ementa é grafada por meio de caracteres que a realcem e explicita, de modo conciso e sob a forma de título, o objeto da lei.","O preâmbulo é grafado por meio de caracteres que o realcem e explicita, de modo conciso e sob a forma de título, o objeto da lei, enquanto a ementa indica o órgão competente e sua base legal.","LC 95/1998, arts. 5º e 6º.","troca ementa e preâmbulo","arts. 5º e 6º")
L(13,"confusao_instituto",3,"O preâmbulo indica o órgão ou a instituição competente para a prática do ato e sua base legal.","A ementa indica o órgão ou a instituição competente para a prática do ato e sua base legal.","LC 95/1998, art. 6º.","troca ementa e preâmbulo","art. 6º")
L(13,"excecao_omitida",3,"O primeiro artigo do texto da lei indicará o objeto da lei e o respectivo âmbito de aplicação.","O objeto da lei e o respectivo âmbito de aplicação serão indicados no preâmbulo, e o primeiro artigo do texto já inaugura a parte normativa.","LC 95/1998, art. 7º, caput.","desloca objeto para o preâmbulo","art. 7º, caput")
L(13,"excecao_omitida",3,"Excetuadas as codificações, cada lei tratará de um único objeto, e a lei não conterá matéria estranha a seu objeto ou a este não vinculada por afinidade, pertinência ou conexão.","Cada lei, inclusive as que não são codificações, poderá tratar de mais de um objeto, desde que todos estejam enumerados no primeiro artigo.","LC 95/1998, art. 7º, I e II.","admite pluralidade de objetos","art. 7º, I e II")
L(13,"caso_concreto",4,"Uma lei que dispõe sobre aposentadoria de servidores e, no último artigo, inclui regra sobre licitações sem relação com o tema contraria o princípio de que a lei não conterá matéria estranha a seu objeto ou a este não vinculada por afinidade, pertinência ou conexão.","Uma lei que dispõe sobre aposentadoria de servidores e, no último artigo, inclui regra sobre licitações sem relação com o tema respeita a LC 95/1998, pois a lei pode conter matéria estranha ao objeto quando ela vier ao final do texto.","LC 95/1998, art. 7º, II.","admite matéria estranha","art. 7º, II")
L(13,"troca_efeito",3,"O âmbito de aplicação da lei será estabelecido de forma tão específica quanto o possibilite o conhecimento técnico ou científico da área respectiva.","O âmbito de aplicação da lei será estabelecido de forma genérica, para que a norma alcance o maior número possível de situações, ainda que o conhecimento técnico da área permita maior especificidade.","LC 95/1998, art. 7º, III.","inverte critério de especificidade","art. 7º, III")
L(13,"excecao_omitida",4,"O mesmo assunto não poderá ser disciplinado por mais de uma lei, exceto quando a subsequente se destine a complementar lei considerada básica, vinculando-se a esta por remissão expressa.","O mesmo assunto poderá ser disciplinado por mais de uma lei, sem necessidade de remissão expressa, desde que a lei posterior revogue tacitamente a anterior.","LC 95/1998, art. 7º, IV.","afasta exceção e remissão","art. 7º, IV")
L(13,"excecao_omitida",3,"A vigência da lei será indicada de forma expressa e de modo a contemplar prazo razoável para que dela se tenha amplo conhecimento, reservada a cláusula 'entra em vigor na data de sua publicação' para as leis de pequena repercussão.","A cláusula 'entra em vigor na data de sua publicação' deve ser adotada em todas as leis, independentemente da repercussão, pois assegura a vigência imediata e o amplo conhecimento do texto.","LC 95/1998, art. 8º, caput.","generaliza cláusula de vigência imediata","art. 8º, caput")
L(13,"confusao_instituto",4,"Na contagem do prazo de vacância, incluem-se a data da publicação e o último dia do prazo, e a lei entra em vigor no dia subsequente à consumação integral do prazo.","Na contagem do prazo de vacância, excluem-se a data da publicação e o último dia do prazo, e a lei entra em vigor no próprio último dia do prazo.","LC 95/1998, art. 8º, § 1º.","inverte regra de contagem","art. 8º, § 1º")
L(13,"caso_concreto",4,"Uma lei publicada em 1º de março, com vacância de trinta dias contados nos termos da LC 95/1998, entra em vigor em 31 de março.","Uma lei publicada em 1º de março, com vacância de trinta dias contados nos termos da LC 95/1998, entra em vigor em 1º de abril, pois a data da publicação não se inclui na contagem.","LC 95/1998, art. 8º, § 1º. Pelo Manual (dia da publicação como dia zero), a data de vigência coincide: 31 de março.","exclui o dia da publicação","art. 8º, § 1º")
L(13,"troca_efeito",3,"As leis que estabeleçam período de vacância devem utilizar a cláusula 'esta lei entra em vigor após decorridos (número de dias) de sua publicação oficial'.","As leis que estabeleçam período de vacância devem utilizar a cláusula 'esta lei entra em vigor na data de sua publicação, produzindo efeitos após o prazo previsto'.","LC 95/1998, art. 8º, § 2º.","altera a cláusula de vacância","art. 8º, § 2º")
L(13,"troca_efeito",3,"A cláusula de revogação deverá enumerar, expressamente, as leis ou disposições legais revogadas.","A cláusula de revogação deverá utilizar a expressão genérica 'revogam-se as disposições em contrário', vedada a enumeração das normas revogadas.","LC 95/1998, art. 9º.","inverte regra da revogação","art. 9º")
L(13,"troca_numero",3,"A LC 95/1998 entrou em vigor no prazo de noventa dias a partir da data de sua publicação.","A LC 95/1998 entrou em vigor na data de sua publicação, por tratar-se de norma de técnica legislativa de pequena repercussão.","LC 95/1998, art. 19.","altera a vigência da LC 95","art. 19")
# ---- atom 18: arts. 10 e 11
L(18,"troca_numero",3,"A unidade básica de articulação dos textos legais é o artigo, indicado pela abreviatura 'Art.', seguida de numeração ordinal até o nono e cardinal a partir deste.","A unidade básica de articulação dos textos legais é o parágrafo, indicado pelo sinal '§', seguido de numeração ordinal até o décimo e cardinal a partir deste.","LC 95/1998, art. 10, I.","troca unidade básica e ponto de corte","art. 10, I")
L(18,"confusao_instituto",3,"Os artigos desdobram-se em parágrafos ou em incisos; os parágrafos, em incisos; os incisos, em alíneas; e as alíneas, em itens.","Os artigos desdobram-se em alíneas; as alíneas, em incisos; os incisos, em parágrafos; e os parágrafos, em itens.","LC 95/1998, art. 10, II.","inverte a hierarquia","art. 10, II")
L(18,"confusao_instituto",3,"Os incisos são representados por algarismos romanos, as alíneas por letras minúsculas e os itens por algarismos arábicos.","Os incisos são representados por letras minúsculas, as alíneas por algarismos romanos e os itens por algarismos arábicos.","LC 95/1998, art. 10, IV.","troca representações","art. 10, IV")
L(18,"excecao_omitida",3,"Os parágrafos são representados pelo sinal gráfico '§', seguido de numeração ordinal até o nono e cardinal a partir deste, usando-se a expressão 'parágrafo único' por extenso quando existente apenas um.","Os parágrafos são representados pela abreviatura 'Par.', seguida de numeração cardinal, usando-se o sinal '§ único' quando existente apenas um.","LC 95/1998, art. 10, III.","altera representação do parágrafo","art. 10, III")
L(18,"confusao_instituto",3,"O agrupamento de artigos pode constituir Subseções; o de Subseções, a Seção; o de Seções, o Capítulo; o de Capítulos, o Título; o de Títulos, o Livro; e o de Livros, a Parte.","O agrupamento de artigos pode constituir Capítulos; o de Capítulos, a Seção; o de Seções, a Subseção; o de Subseções, o Título; e o de Títulos, o Livro.","LC 95/1998, art. 10, V.","inverte a hierarquia dos agrupamentos","art. 10, V")
L(18,"confusao_instituto",3,"Os Capítulos, Títulos, Livros e Partes são grafados em letras maiúsculas e identificados por algarismos romanos, ao passo que as Subseções e Seções são identificadas em algarismos romanos, grafadas em letras minúsculas e postas em negrito ou em caracteres que as coloquem em realce.","Os Capítulos, Títulos, Livros e Partes são grafados em letras minúsculas e identificados por algarismos arábicos, ao passo que as Subseções e Seções são grafadas em letras maiúsculas e sem realce.","LC 95/1998, art. 10, VI e VII.","troca grafia dos agrupamentos","art. 10, VI e VII")
L(18,"excecao_omitida",3,"A composição dos agrupamentos de artigos pode compreender também agrupamentos em Disposições Preliminares, Gerais, Finais ou Transitórias, conforme necessário.","A composição dos agrupamentos de artigos limita-se a Subseções, Seções, Capítulos, Títulos, Livros e Partes, sendo vedados agrupamentos em Disposições Preliminares, Gerais, Finais ou Transitórias.","LC 95/1998, art. 10, VIII.","veda agrupamentos admitidos","art. 10, VIII")
L(18,"excecao_omitida",2,"As disposições normativas serão redigidas com clareza, precisão e ordem lógica.","As disposições normativas serão redigidas com ênfase na expressividade, na variedade vocabular e no estilo elaborado.","LC 95/1998, art. 11, caput.","troca princípios de redação","art. 11, caput")
L(18,"excecao_omitida",3,"Para a obtenção de clareza, devem-se usar as palavras e as expressões em seu sentido comum, salvo quando a norma versar sobre assunto técnico, hipótese em que se empregará a nomenclatura própria da área em que se esteja legislando.","Para a obtenção de clareza, devem-se usar termos técnicos e raros, ainda que a norma não verse sobre assunto técnico, para conferir maior elegância ao texto.","LC 95/1998, art. 11, I, a.","inverte regra da clareza","art. 11, I, a")
L(18,"troca_efeito",3,"Para a obtenção de clareza, devem-se usar frases curtas e concisas e construir as orações na ordem direta, evitando preciosismo, neologismo e adjetivações dispensáveis.","Para a obtenção de clareza, devem-se usar frases longas e construir as orações na ordem inversa, valorizando o preciosismo e o neologismo.","LC 95/1998, art. 11, I, b e c.","inverte regras de clareza","art. 11, I, b e c")
L(18,"troca_efeito",3,"Deve-se buscar a uniformidade do tempo verbal em todo o texto das normas legais, dando preferência ao tempo presente ou ao futuro simples do presente, e usar a pontuação de forma judiciosa, evitando os abusos de caráter estilístico.","Deve-se alternar os tempos verbais ao longo do texto das normas legais, dando preferência ao pretérito perfeito, e usar a pontuação de forma expressiva, valorizando os recursos de caráter estilístico.","LC 95/1998, art. 11, I, d e e.","inverte regras de tempo verbal e pontuação","art. 11, I, d e e")
L(18,"troca_efeito",3,"Para a obtenção de precisão, deve-se expressar a ideia, quando repetida no texto, por meio das mesmas palavras, evitando o emprego de sinonímia com propósito meramente estilístico.","Para a obtenção de precisão, deve-se variar as palavras sempre que a ideia for repetida no texto, empregando sinônimos com propósito estilístico.","LC 95/1998, art. 11, II, b.","inverte regra da sinonímia","art. 11, II, b")
L(18,"excecao_omitida",2,"Para a obtenção de precisão, deve-se evitar o emprego de expressão ou palavra que confira duplo sentido ao texto.","Para a obtenção de precisão, admite-se o emprego de expressão que confira duplo sentido ao texto, desde que a interpretação seja definida na jurisprudência.","LC 95/1998, art. 11, II, c.","admite duplo sentido","art. 11, II, c")
L(18,"troca_efeito",3,"Devem ser escolhidos termos que tenham o mesmo sentido e significado na maior parte do território nacional, evitando-se o uso de expressões locais ou regionais.","Devem ser preferidas as expressões locais ou regionais, para aproximar a norma da realidade de cada Estado.","LC 95/1998, art. 11, II, d.","inverte regra de expressões regionais","art. 11, II, d")
L(18,"excecao_omitida",4,"Devem ser usadas apenas siglas consagradas pelo uso, observado o princípio de que a primeira referência no texto seja acompanhada de explicitação de seu significado.","Podem ser criadas novas siglas em cada lei, e a sigla deve ser usada desde a primeira referência, sem explicitação de seu significado.","LC 95/1998, art. 11, II, e.","inverte regra de siglas","art. 11, II, e")
L(18,"excecao_omitida",4,"Devem-se grafar por extenso quaisquer referências a números e percentuais, exceto data, número de lei e os casos em que houver prejuízo para a compreensão do texto.","Devem-se grafar em algarismos todas as referências a números e percentuais, para assegurar a precisão, vedada a escrita por extenso.","LC 95/1998, art. 11, II, f.","inverte regra e omite exceções","art. 11, II, f")
L(18,"troca_efeito",3,"Deve-se indicar expressamente o dispositivo objeto de remissão, em vez de usar as expressões 'anterior', 'seguinte' ou equivalentes.","Para remeter a outro dispositivo, devem ser usadas as expressões 'anterior', 'seguinte' ou equivalentes, em vez da indicação expressa do dispositivo.","LC 95/1998, art. 11, II, g.","inverte regra de remissão","art. 11, II, g")
L(18,"excecao_omitida",3,"Para a obtenção de ordem lógica, devem-se reunir sob as categorias de agregação (subseção, seção, capítulo, título e livro) apenas as disposições relacionadas com o objeto da lei, e restringir o conteúdo de cada artigo a um único assunto ou princípio.","Para a obtenção de ordem lógica, podem-se reunir sob as categorias de agregação disposições alheias ao objeto da lei, desde que sob o mesmo capítulo, e cada artigo pode reunir vários assuntos ou princípios.","LC 95/1998, art. 11, III, a e b.","admite disposições alheias e pluralidade","art. 11, III, a e b")
L(18,"confusao_instituto",3,"Os aspectos complementares à norma enunciada no caput do artigo e as exceções à regra por este estabelecida devem ser expressos por meio dos parágrafos, e as discriminações e enumerações, por meio dos incisos, alíneas e itens.","Os aspectos complementares à norma enunciada no caput do artigo e as exceções à regra devem ser expressos por meio dos incisos, e as discriminações e enumerações, por meio dos parágrafos.","LC 95/1998, art. 11, III, c e d.","troca parágrafos e incisos","art. 11, III, c e d")
# ---- atom 19: art. 12 e técnica de alteração
L(19,"confusao_instituto",3,"A alteração da lei será feita mediante reprodução integral em novo texto, quando se tratar de alteração considerável; mediante revogação parcial; e, nos demais casos, por substituição, no próprio texto, do dispositivo alterado, ou por acréscimo de dispositivo novo.","A alteração da lei será feita sempre mediante reprodução integral em novo texto, vedadas a revogação parcial e a substituição ou o acréscimo de dispositivos no próprio texto.","LC 95/1998, art. 12, I a III.","admite só reprodução integral","art. 12, I a III")
L(19,"caso_concreto",4,"Para acrescentar um novo artigo entre os arts. 5º e 6º de uma lei, usa-se a numeração 'Art. 5º-A', sem renumerar os artigos seguintes.","Para acrescentar um novo artigo entre os arts. 5º e 6º de uma lei, renumeram-se os artigos seguintes, de modo que o novo artigo passe a ser o 6º, cabendo à lei alteradora corrigir as remissões.","LC 95/1998, art. 12, III, b.","permite renumeração de artigos","art. 12, III, b")
L(19,"excecao_omitida",5,"A vedação de renumeração prevista no art. 12, III, b, da LC 95/1998 alcança os artigos e as unidades superiores ao artigo (como seções e capítulos); quanto às unidades em que se desdobra o artigo, é admissível a reordenação interna, identificando-se o artigo modificado com a sigla NR.","A vedação de renumeração prevista no art. 12, III, b, da LC 95/1998 alcança os parágrafos, incisos, alíneas e itens, sem qualquer possibilidade de reordenação interna das unidades em que se desdobra o artigo.","LC 95/1998, art. 12, III, b e d.","amplia a vedação a unidades internas","art. 12, III, b e d")
L(19,"excecao_omitida",3,"É vedado o aproveitamento do número de dispositivo revogado, vetado, declarado inconstitucional pelo STF ou de execução suspensa pelo Senado Federal, devendo a lei alterada manter essa indicação, seguida da expressão 'revogado', 'vetado' ou equivalente.","Pode ser aproveitado o número de dispositivo revogado ou vetado, para que a numeração do texto não fique com lacunas, ressalvado o dispositivo declarado inconstitucional pelo STF.","LC 95/1998, art. 12, III, c.","permite reaproveitar número","art. 12, III, c")
L(19,"troca_efeito",4,"O artigo que tiver sua redação alterada, suprimida ou acrescida é identificado com as letras 'NR' maiúsculas, entre parênteses, uma única vez ao seu final.","Cada dispositivo que receba nova redação é identificado com as letras 'nr' minúsculas, entre colchetes, no início do dispositivo, repetidas a cada parágrafo alterado.","LC 95/1998, art. 12, III, d.","altera forma e posição do NR","art. 12, III, d")
L(19,"excecao_omitida",2,"Para os fins da LC 95/1998, o termo 'dispositivo' refere-se a artigos, parágrafos, incisos, alíneas ou itens.","Para os fins da LC 95/1998, o termo 'dispositivo' refere-se a artigos e parágrafos, não alcançando incisos, alíneas e itens.","LC 95/1998, art. 12, parágrafo único.","restringe conceito de dispositivo","art. 12, parágrafo único")
T(19,"excecao_omitida",3,"O artigo de alteração deve fazer menção expressa ao ato normativo alterado, sendo vedado dispor sobre alterações de mais de uma norma no mesmo artigo ou dividir alterações do mesmo ato normativo em diversos artigos da norma alteradora.","O artigo de alteração deve reunir, para economia do texto, as alterações de várias normas distintas, e pode dividir as alterações do mesmo ato normativo em diversos artigos da norma alteradora, distinguindo dispositivos alterados e acrescidos.","Manual, item 17.1.1.","inverte regras do artigo de alteração","item 17.1.1")
T(19,"excecao_omitida",4,"Na alteração parcial de artigo, o uso de linha pontilhada para indicar a manutenção do trecho é obrigatório, e a inexistência de linha pontilhada não dispensa a revogação expressa de parágrafo.","Na alteração parcial de artigo, o uso de linha pontilhada é facultativo, e a inexistência de linha pontilhada equivale à revogação do parágrafo, dispensando a revogação expressa.","Manual, item 17.1.2.","torna facultativa a linha pontilhada","item 17.1.2")
T(19,"confusao_instituto",4,"Segundo o Manual, 'republicação' designa a hipótese de o texto publicado não corresponder ao original assinado pela autoridade, ao passo que 'retificação' refere-se ao texto publicado que corresponde ao subscrito pela autoridade, mas contém lapso manifesto.","Segundo o Manual, 'retificação' designa a hipótese de o texto publicado não corresponder ao original assinado pela autoridade, ao passo que 'republicação' refere-se ao texto publicado que corresponde ao subscrito pela autoridade, mas contém lapso manifesto.","Manual, item 17.2.","inverte retificação e republicação","item 17.2")
T(19,"consequencia",4,"Como os atos normativos somente produzem efeitos após a publicação no Diário Oficial da União, a republicação do texto corrigido não gera efeitos retroativos.","A republicação do texto corrigido gera efeitos retroativos à data da primeira publicação do ato normativo, já que apenas restabelece o original assinado pela autoridade.","Manual, item 17.2.","atribui retroatividade à republicação","item 17.2")
T(19,"confusao_instituto",3,"A correção de erro material que não afete a substância do ato singular de caráter pessoal é realizada por apostila, cuja competência é do setor de recursos humanos do órgão e que dispensa nova assinatura da autoridade que subscreveu o ato originário.","A correção de erro material em ato normativo de caráter geral é realizada por apostila, cuja competência é da autoridade que subscreveu o ato originário e que exige nova assinatura dessa autoridade.","Manual, item 18.1.","aplica apostila a ato geral e exige assinatura","item 18.1")
T(19,"caso_concreto",4,"Não se aplica o apostilamento quando a essência do cargo em comissão ou da função de confiança foi alterada, como na alteração do nível hierárquico ou na transformação de atribuição de assessoramento em atribuição de chefia.","Aplica-se o apostilamento mesmo quando a essência do cargo em comissão foi alterada, como na alteração do nível hierárquico ou na transformação de atribuição de assessoramento em atribuição de chefia.","Manual, item 18.1.","amplia cabimento da apostila","item 18.1")
# ---- atom 20: consolidação e disposições finais
L(20,"confusao_instituto",3,"A consolidação consiste na integração de todas as leis pertinentes a determinada matéria num único diploma legal, revogando-se formalmente as leis incorporadas à consolidação, sem modificação do alcance nem interrupção da força normativa dos dispositivos consolidados.","A consolidação consiste na alteração do mérito das leis pertinentes a determinada matéria, com criação de novos direitos e obrigações, mantendo-se em vigor as leis incorporadas.","LC 95/1998, art. 13, § 1º.","atribui alteração de mérito","art. 13, § 1º")
L(20,"excecao_omitida",4,"Preservado o conteúdo normativo original dos dispositivos consolidados, podem ser feitas, nos projetos de lei de consolidação, alterações como a fusão de disposições repetitivas, a atualização da denominação de órgãos e entidades e a homogeneização terminológica do texto.","Na consolidação, é vedada qualquer alteração formal do texto, inclusive a fusão de disposições repetitivas e a atualização da denominação de órgãos e entidades, ainda que preservado o conteúdo normativo.","LC 95/1998, art. 13, § 2º.","veda alterações formais","art. 13, § 2º")
L(20,"excecao_omitida",5,"Nos projetos de lei de consolidação, são admitidas, entre outras, a atualização do valor de penas pecuniárias com base em indexação padrão, a supressão de dispositivos declarados inconstitucionais pelo STF e a indicação de dispositivos não recepcionados pela Constituição.","Nos projetos de lei de consolidação, são vedadas a atualização do valor de penas pecuniárias, a supressão de dispositivos declarados inconstitucionais pelo STF e a indicação de dispositivos não recepcionados pela Constituição.","LC 95/1998, art. 13, § 2º, VI, IX e X.","veda alterações admitidas","art. 13, § 2º")
L(20,"excecao_omitida",4,"As providências de supressão de dispositivos inconstitucionais, de indicação de dispositivos não recepcionados e de declaração de revogação de dispositivos implicitamente revogados devem ser expressa e fundadamente justificadas, com indicação precisa das fontes de informação que lhes serviram de base.","As providências de supressão de dispositivos inconstitucionais, de indicação de dispositivos não recepcionados e de declaração de revogação de dispositivos implicitamente revogados dispensam justificativa, por decorrerem diretamente da Constituição.","LC 95/1998, art. 13, § 3º.","dispensa justificativa","art. 13, § 3º")
L(20,"excecao_omitida",3,"Não serão objeto de consolidação as medidas provisórias ainda não convertidas em lei.","As medidas provisórias em vigor, ainda que não convertidas em lei, serão objeto de consolidação juntamente com as leis pertinentes à matéria.","LC 95/1998, art. 14, § 1º.","inclui MPs na consolidação","art. 14, § 1º")
L(20,"troca_autoridade",4,"A Mesa Diretora do Congresso Nacional, a de qualquer de suas Casas e qualquer membro ou Comissão da Câmara dos Deputados, do Senado Federal ou do Congresso Nacional podem formular projeto de lei de consolidação.","Somente a Mesa Diretora da Câmara dos Deputados e o Presidente da República podem formular projeto de lei de consolidação.","LC 95/1998, art. 14, § 2º.","restringe legitimados","art. 14, § 2º")
L(20,"troca_efeito",3,"A apreciação dos projetos de lei de consolidação pelo Poder Legislativo será feita na forma do Regimento Interno de cada uma de suas Casas, em procedimento simplificado, visando a dar celeridade aos trabalhos.","A apreciação dos projetos de lei de consolidação pelo Poder Legislativo seguirá o rito ordinário de tramitação das leis complementares, vedado procedimento simplificado, em razão do impacto sobre a legislação vigente.","LC 95/1998, art. 14, II.","afasta procedimento simplificado","art. 14, II")
L(20,"excecao_omitida",4,"Também é admitido projeto de lei de consolidação destinado exclusivamente a declarar a revogação de leis e dispositivos implicitamente revogados ou cuja eficácia ou validade esteja completamente prejudicada, ou a incluir dispositivos ou diplomas esparsos em leis preexistentes.","Não é admitido projeto de lei de consolidação destinado exclusivamente a declarar a revogação de leis implicitamente revogadas, pois a consolidação exige a integração de todas as leis de uma matéria num único diploma.","LC 95/1998, art. 14, § 3º.","nega consolidação limitada","art. 14, § 3º")
L(20,"troca_autoridade",4,"Na primeira sessão legislativa de cada legislatura, a Mesa do Congresso Nacional promoverá a atualização da Consolidação das Leis Federais Brasileiras, incorporando as coletâneas que a integram às emendas constitucionais, leis, decretos legislativos e resoluções promulgadas durante a legislatura imediatamente anterior.","No início de cada sessão legislativa, o Poder Executivo promoverá a atualização da Consolidação das Leis Federais Brasileiras, incorporando às coletâneas as leis e os decretos editados no ano anterior.","LC 95/1998, art. 15.","troca autoridade e periodicidade","art. 15")
L(20,"troca_numero",4,"O Poder Executivo, até cento e oitenta dias do início do primeiro ano do mandato presidencial, promoverá a atualização das coletâneas de decretos e demais atos de conteúdo normativo e geral, incorporando os atos editados no último quadriênio.","O Poder Executivo, até noventa dias do início de cada ano do mandato presidencial, promoverá a atualização das coletâneas de decretos e demais atos de conteúdo normativo e geral, incorporando os atos editados no último exercício.","LC 95/1998, art. 17.","troca prazo e periodicidade","art. 17")
L(20,"troca_efeito",3,"Eventual inexatidão formal de norma elaborada mediante processo legislativo regular não constitui escusa válida para o seu descumprimento.","Eventual inexatidão formal de norma elaborada mediante processo legislativo regular constitui escusa válida para o seu descumprimento.","LC 95/1998, art. 18.","inverte regra do art. 18","art. 18")
L(20,"generalizacao",4,"Segundo a doutrina e a jurisprudência majoritárias, a inobservância das regras de técnica legislativa da LC 95/1998, por si só, não torna inválida a lei aprovada em processo legislativo regular.","Segundo a doutrina e a jurisprudência majoritárias, a inobservância das regras de técnica legislativa da LC 95/1998 torna, por si só, inconstitucional qualquer lei aprovada em processo legislativo regular.","LC 95/1998, art. 18; art. 18-A vetado. Entendimento de doutrina e jurisprudência.","exagera consequência da violação","art. 18", True)
# ---- atom 21: atos normativos no Manual de Redação (item 19)
T(21,"confusao_instituto",3,"Segundo o Manual, o ato normativo é estruturado em três partes básicas: a parte preliminar (epígrafe, ementa e preâmbulo), a parte normativa e a parte final (medidas de implementação, disposições transitórias, cláusula de revogação, quando couber, e cláusula de vigência).","Segundo o Manual, o ato normativo é estruturado em três partes básicas: a parte preliminar (epígrafe e ementa), a parte normativa (preâmbulo e normas substantivas) e a parte final (cláusula de revogação e fecho).","Manual, item 19.1.1.1.","redistribui elementos das partes","item 19.1.1.1")
T(21,"excecao_omitida",4,"São elementos essenciais para a adequada redação de todo ato normativo a ementa, a autoria, a parte normativa e a cláusula de vigência; os demais elementos podem ou não constar, conforme a natureza e o objeto do ato.","São elementos essenciais para a adequada redação de todo ato normativo a epígrafe, o preâmbulo, a cláusula de revogação e as disposições transitórias; os demais elementos podem ou não constar.","Manual, item 19.1.1.1.","troca elementos essenciais","item 19.1.1.1")
T(21,"norma_culta",3,"A epígrafe é a parte do ato que o qualifica na ordem jurídica e o situa no tempo, por meio da denominação, da numeração e da data, devendo ser grafada em maiúsculas e sem ponto final.","A epígrafe é a parte do ato que resume seu conteúdo, por meio da denominação e do objeto, devendo ser grafada em minúsculas e com ponto final.","Manual, item 19.1.1.2.","mistura epígrafe e ementa","item 19.1.1.2")
T(21,"excecao_omitida",4,"A ementa deve resumir o tema central ou a finalidade principal da lei, evitando-se mencionar apenas um tópico genérico acompanhado da expressão 'e dá outras providências', admitida só em atos de excepcional extensão e multiplicidade de temas.","A ementa deve concluir com a expressão 'e dá outras providências' em todos os atos normativos, a fim de dispensar a menção a temas secundários da lei.","Manual, item 19.1.1.3.","recomenda fórmula desaconselhada","item 19.1.1.3")
T(21,"confusao_instituto",3,"O preâmbulo contém a declaração do nome da autoridade, do cargo em que se encontra investida e da atribuição constitucional em que se funda, quando for o caso, e a ordem de execução ou mandado de cumprimento do ato normativo.","O preâmbulo contém a síntese do conteúdo do ato normativo, a justificativa de sua edição e os considerandos que fundamentam a decisão da autoridade.","Manual, item 19.1.1.4.","atribui conteúdo de ementa e considerandos","item 19.1.1.4")
T(21,"caso_concreto",5,"O decreto regulamentar extrai seu fundamento de validade do art. 84, IV, da Constituição combinado com a lei que regulamenta, sendo grave equívoco indicar o art. 84, IV, isoladamente como fundamento.","O decreto regulamentar extrai seu fundamento de validade diretamente do art. 84, IV, da Constituição, que isoladamente basta como fundamento, sendo grave equívoco citar a lei regulamentada no preâmbulo.","Manual, item 19.1.1.4.","dispensa a lei regulamentada","item 19.1.1.4")
T(21,"confusao_instituto",4,"O decreto organizacional (autônomo) deve estar fundamentado no art. 84, VI, alínea 'a', da Constituição, e não cabe mencionar ato normativo infraconstitucional como seu fundamento de validade.","O decreto organizacional (autônomo) deve estar fundamentado no art. 84, IV, da Constituição combinado com a lei que organiza a administração, devendo citar a lei como fundamento de validade.","Manual, item 19.1.1.4.","troca fundamento do decreto autônomo","item 19.1.1.4")
T(21,"excecao_omitida",3,"Exceto na hipótese de atos internacionais, não é mais admitida a colocação de considerandos em atos normativos; os esclarecimentos sobre o pretendido com o ato constam da Exposição de Motivos e dos pareceres técnicos e jurídicos.","É recomendada a colocação de considerandos em todos os atos normativos, inclusive nos atos internacionais, a fim de esclarecer o pretendido com o ato, dispensando-se a Exposição de Motivos.","Manual, item 19.1.1.4.","recomenda considerandos","item 19.1.1.4")
T(21,"confusao_instituto",4,"Indicar o âmbito de aplicação do ato normativo não se confunde com especificar o tema central, já constante da ementa; significa indicar as relações jurídicas a que a norma se destina, como direito público ou privado, esfera federal ou todos os entes, ou apenas o Poder Executivo.","Indicar o âmbito de aplicação do ato normativo equivale a especificar o tema central, já constante da ementa, sendo desnecessário indicar as relações jurídicas a que a norma se destina.","Manual, item 19.1.1.5.","equipara âmbito a tema central","item 19.1.1.5")
T(21,"norma_culta",3,"Na grafia dos dispositivos, a abreviatura 'Art.' tem inicial maiúscula no início do texto e 'art.' tem inicial minúscula ao longo do texto; o artigo com incisos é encerrado por dois-pontos; e, havendo um só parágrafo, grafa-se 'Parágrafo único.' e não '§ único'.","Na grafia dos dispositivos, a abreviatura 'Art.' tem inicial maiúscula ao longo do texto; o artigo com incisos é encerrado por ponto-final; e, havendo um só parágrafo, grafa-se '§ único.' com o sinal de parágrafo.","Manual, itens 16.2.1 e 16.2.2.","altera grafia de artigo e parágrafo","itens 16.2.1 e 16.2.2")
T(21,"norma_culta",4,"Segundo a praxe federal, a denominação do assunto de cada unidade de agrupamento é iniciada pela preposição 'De' combinada com o artigo definido (como 'Dos direitos e garantias fundamentais'); as seções têm iniciais maiúsculas em negrito, ao passo que capítulos e títulos são grafados em maiúsculas, sem negrito.","Segundo a praxe federal, a denominação do assunto de cada unidade de agrupamento é iniciada pela conjunção 'E' (como 'E os direitos e garantias fundamentais'); as seções são grafadas em maiúsculas sem negrito, ao passo que capítulos e títulos têm iniciais maiúsculas em negrito.","Manual, item 16.2.4.","troca denominação e grafia dos agrupamentos","item 16.2.4")
T(21,"excecao_omitida",3,"Para atos normativos de baixa complexidade, a regra geral é a organização em torno de meros artigos, sendo equivocado dividi-los em capítulos e seções a ponto de gerar vários capítulos compostos de um só artigo.","Para atos normativos de baixa complexidade, a regra geral é a divisão em capítulos e seções, ainda que cada capítulo reúna um só artigo, para dar aparência de maior complexidade técnica.","Manual, item 16.2.","recomenda divisão excessiva","item 16.2")
T(21,"excecao_omitida",3,"Desde a LC 95/1998 admite-se somente a cláusula de revogação específica, sendo vedada a fórmula 'Revogam-se as disposições em contrário', e a cláusula é subdividida em incisos quando houver mais de um ato revogado.","Desde a LC 95/1998 admitem-se as cláusulas de revogação específica e geral, sendo recomendada a fórmula 'Revogam-se as disposições em contrário' quando houver mais de um ato revogado.","Manual, item 19.1.2.2.","admite revogação genérica","item 19.1.2.2")
T(21,"troca_numero",3,"Se a lei não definir data ou prazo para entrada em vigor, aplica-se o art. 1º da LINDB, segundo o qual, exceto disposição em contrário, a lei começa a vigorar em todo o país quarenta e cinco dias depois de publicada, embora não seja de boa técnica deixar de prever a vigência de modo expresso.","Se a lei não definir data ou prazo para entrada em vigor, aplica-se o art. 1º da LINDB, segundo o qual, exceto disposição em contrário, a lei começa a vigorar em todo o país trinta dias depois de publicada, o que dispensa a previsão expressa de vigência.","Manual, item 19.1.2.3.","troca prazo da LINDB","item 19.1.2.3")
T(21,"excecao_omitida",4,"No Poder Executivo federal, a tendência é reduzir as hipóteses de entrada em vigor imediata, de modo que a cláusula 'entra em vigor na data de sua publicação' não deve ser posta de modo acrítico e automático ao final de todas as normas; a vacatio legis é indicada, por exemplo, para atos de maior repercussão ou que exijam medidas de adaptação.","No Poder Executivo federal, a tendência é ampliar as hipóteses de entrada em vigor imediata, de modo que a cláusula 'entra em vigor na data de sua publicação' deve ser posta ao final de todas as normas, dispensada a vacatio legis para atos de maior repercussão.","Manual, item 19.1.2.3.","inverte tendência da vigência","item 19.1.2.3")
T(21,"confusao_instituto",5,"Segundo o Manual, na contagem do prazo de vacância considera-se o dia da publicação como dia zero e a data de entrada em vigor como o dia da consumação integral do prazo, e a contagem não é interrompida ou suspensa em fins de semana ou feriados.","Segundo o Manual, na contagem do prazo de vacância considera-se o dia da publicação como primeiro dia do prazo, e a contagem é suspensa em fins de semana e feriados, transferindo-se a entrada em vigor para o primeiro dia útil seguinte.","Manual, item 19.1.2.3. A LC 95/1998 descreve a contagem de outro modo (inclusão da data da publicação e do último dia, com vigência no dia subsequente), com o mesmo resultado prático.","altera contagem e suspensão","item 19.1.2.3")
T(21,"norma_culta",3,"O fecho de lei ou de decreto traz a referência à contagem dos anos em relação à Independência e à República, como em 'Brasília, 1º de dezembro de 2018; 197º da Independência e 130º da República.'","O fecho de lei ou de decreto traz a referência à contagem dos anos em relação à promulgação da Constituição e à data da proposição, como em 'Brasília, 1º de dezembro de 2018; 30º da Constituição.'","Manual, item 19.1.1.6.","troca marcos do fecho","item 19.1.1.6")
T(21,"troca_autoridade",4,"Os atos submetidos ao Presidente da República devem ser referendados pelos Ministros de Estado que respondam pela matéria (art. 87, parágrafo único, I, da CF), e a referenda é competência privativa de Ministros de Estado, não podendo ser delegada nem exercida por autoridades apenas equiparadas.","Os atos submetidos ao Presidente da República devem ser referendados pelo Chefe da Casa Civil, e a referenda pode ser delegada a secretários-executivos e autoridades equiparadas a Ministros de Estado.","Manual, item 19.1.3.","troca competência da referenda","item 19.1.3")
T(21,"troca_autoridade",4,"A referenda dos atos de nomeação de Ministro de Estado cabe ao Ministro de Estado da Justiça, e a dos atos propostos por autoridades subordinadas diretamente ao Presidente que não sejam Ministros de Estado cabe ao Ministro Chefe da Casa Civil.","A referenda dos atos de nomeação de Ministro de Estado cabe ao Ministro Chefe da Casa Civil, e a dos atos propostos por autoridades subordinadas diretamente ao Presidente que não sejam Ministros de Estado cabe ao Ministro de Estado da Justiça.","Manual, item 19.1.3.","inverte competências de referenda","item 19.1.3")
